import std.io
import std.fs

pub fn main() effect io -> Result<(), fs.FsError> {
    match fs.makeDir("ld") {
        Ok(_) => { io.println("mkdir-ok") }
        Err(_) => { io.println("mkdir-bad") }
    }
    match fs.writeFile("ld/z.txt", "z") {
        Ok(_) => { io.println("z-ok") }
        Err(_) => { io.println("z-bad") }
    }
    match fs.writeFile("ld/M.txt", "m") {
        Ok(_) => { io.println("m-ok") }
        Err(_) => { io.println("m-bad") }
    }
    match fs.writeFile("ld/a.txt", "a") {
        Ok(_) => { io.println("a-ok") }
        Err(_) => { io.println("a-bad") }
    }
    match fs.listDir("ld") {
        Ok(xs) => {
            for n in xs { io.println("entry:${n}") }
        }
        Err(_) => { io.println("list-bad") }
    }
    return Ok(())
}
